# gen-acts2.ps1 — full activity guides with package cards. Pure ASCII.
. "$PSScriptRoot/gen-common.ps1"
function New-Act($slug,$title,$imgk,$lead,$what,$where,$time,$cost,$fit,$pkgs,$related){
  $im=$IMG[$imgk]
  $cards=""; foreach($p in $pkgs){ if($p.Count -gt 3){ $cards+=Card-Pkg $p[0] $p[1] $p[2] $p[3] $p[4] $imgk } else { $cards+=Card-Dest $p[0] $p[1] $p[2] $imgk } }
  $faqs=Faq-Activity $title $where $cost $fit
  $body=Crumb @('<a href="/">Home</a>','<a href="/activities/">Activities</a>',$title)
  $body+="<div class=`"hero`"><img class=`"bg`" src=`"$($im[0])`" alt=`"$($im[1])`"><div class=`"hero-in`"><p class=`"eyebrow`">Activity guide</p><h1>$title</h1><p class=`"sub`">$lead</p><div class=`"hero-ctas`"><a class=`"btn btn-g`" href=`"/request-proposal/`">Add to my safari</a><a class=`"btn btn-wa`" data-wa data-wa-pkg=`"$title`" href=`"#`">WhatsApp</a></div></div></div>"
  $body+="<section class=`"block`"><div class=`"wrap`"><h2>What it is</h2><p class=`"lead`">$what</p>"
  $body+="<h2>Where it is available</h2><p>$where</p><h2>Best time</h2><p>$time</p><h2>Cost</h2><p>$cost</p><h2>Who it suits</h2><p>$fit</p>"
  $body+="<h2>Trips featuring this activity</h2><div class=`"grid g3`">$cards</div>"
  $body+=(Faq-List $faqs)+"<h2>Related</h2><p>$related</p>"
  $body+=(CTA-Band "Add this to your safari" "One proposal, all activities placed correctly." $title)+"</div></section></main>"
  $canon="https://www.adventuresafariafrica.com/activities/$slug/"
  $html=Shell $title $lead $canon $body ('<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"'+$title+'"}</script>'+(Faq-Schema $faqs))
  $html | Out-File -FilePath "activities/$slug.html" -Encoding utf8
  "act: $slug"
}
New-Act "game-drives" "Game Drives: How They Work, Times & Private vs Shared" "KE" "Dawn and afternoon drives in open 4x4s are the core of every safari - here is how they actually work." "A game drive is a 2 to 4-hour circuit in an open-sided 4x4 with a pop-up roof, run at dawn (6-9am) and afternoon (3:30-6:30pm) when predators move. Full-day picnic drives suit Migration waiting days." "Every park on every itinerary; private concessions add off-road and night options." "Year-round; dry seasons concentrate game, green seasons cut crowds." "Included in all safari pricing - private vehicles cost more for two, converge at four plus." "Everyone - no fitness needed. Photographers should request private vehicles and beanbags." @(@("/tanzania-safari/7-day-tanzania-safari/","7-Day Tanzania Safari","7 days | Classic","From $3,450","The definitive game-drive week."),@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya Safari","7 days | Classic","From $3,100","Mara, Amboseli and lakes.")) '<a href="/activities/">All activities</a> | <a href="/travel-guide/">Travel guide</a> | <a href="/tanzania-safari/">Tanzania</a>'
New-Act "walking-safaris" "Walking Safaris: On Foot With an Armed Guide" "TZ" "Tracks, birds, wind and adrenaline: 1 to 3-hour walks that change how you see the bush." "Walks with an armed professional guide focus on tracks, dung, birds and small wonders vehicles rush past - plus the honest thrill of approaching big game on foot." "Tarangire and Ruaha buffers, Nyerere, South African and Botswana private concessions. Minimum age usually 16." "Dry season for comfortable walking; green season for birds and flowers." "Usually 30 to 80 dollars per person added to a driving day; multi-day walking trails cost more." "Reasonably mobile travelers 16-plus. Pair with drives, never replace them." @(@("/southern-tanzania-safari/4-day-nyerere-safari/","4-Day Nyerere Safari","4 days | Boats + walks","From $1,750","River, road and foot."),@("/botswana-safari/8-day-botswana-safari/","8-Day Okavango and Chobe","8 days","From $7,400","Walks plus mokoro and drives.")) '<a href="/national-parks/ruaha/">Ruaha</a> | <a href="/national-parks/nyerere/">Nyerere</a> | <a href="/activities/">All activities</a>'
New-Act "night-safaris" "Night Safaris: Bushbabies, Aardvarks & Hunting Lions" "SA" "Spotlit drives after dinner reveal the nocturnal shift - legal only where concessions allow." "After dinner, a spotlight sweep for bushbabies, genets, aardvarks and hunting lions. National parks forbid night driving, so this runs in private concessions only." "Sabi Sand, Timbavati, Khwai, Moremi buffers, Mara conservancies." "Dry season; new-moon darkness is best for nocturnal species." "Included in concession stays; 50 to 100 dollars per person as an add-on elsewhere." "All ages at most lodges; a highlight for children spotting with the tracker." @(@("/south-africa-safari/5-day-kruger-safari/","5-Day Kruger Safari","5 days | Sabi Sand","From $2,800","Night drives included."),@("/botswana-safari/8-day-botswana-safari/","8-Day Botswana","8 days","From $7,400","Concession freedoms.")) '<a href="/national-parks/kruger/">Kruger</a> | <a href="/activities/">All activities</a>'
New-Act "hot-air-balloon-safari" "Hot-Air Balloon Safaris: Cost, Worth & Where" "MIG" "Dawn flights plus champagne bush breakfast over the herds - worth it once." "A one-hour dawn flight drifting over the plains as herds move below, landing to a full bush breakfast with sparkling wine. Silent, smooth, unforgettable." "Central Serengeti, northern Serengeti, Masai Mara, Tarangire. Minimum age usually 7; weight limits apply." "Year-round where offered; calving and crossing seasons add drama below." "550 to 600 dollars per person. Book at proposal stage - seats sell out months ahead." "Most travelers except the vertigo-prone and under-7s. Photographers: fast shutter, no tripods." @(@("/tanzania-safari/7-day-tanzania-safari/","7-Day Tanzania Safari","7 days","From $3,450","Add a balloon dawn."),@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya Safari","7 days","From $3,100","Mara balloon option."),@("/tanzania-migration-safari/7-day-migration-safari/","7-Day Migration Safari","7 days","From $3,800","Balloon over herds.")) '<a href="/great-migration/">Migration hub</a> | <a href="/activities/">All activities</a>'
New-Act "chimpanzee-trekking" "Chimpanzee Trekking in Kibale: Success, Cost & Pairing" "UG" "Half-day tracking with 98-percent success - the perfect gorilla companion." "Track habituated chimp communities through Kibale forest: noisy, fast, arboreal chaos utterly different from gorillas. Permits around 250 dollars." "Kibale Forest primarily; also Budongo and Kyambura. Minimum age usually 12-15 by location." "Year-round; chimps active daily. Dry months firmest underfoot." "Permit plus guide fees; full-day habituation experiences cost more." "Most fitness levels - far easier than gorilla trekking. Superb for teens." @(@("/uganda-safari/7-day-uganda-safari/","7-Day Primates + Wildlife","7 days","From $4,100","Chimps, lions, gorillas."),@("/uganda-gorilla-trekking/5-day-uganda-gorilla/","5-Day Gorillas + Chimps","5 days","From $3,550","The primate double.")) '<a href="/activities/gorilla-trekking/">Gorilla guide</a> | <a href="/national-parks/kibale/">Kibale</a>'
New-Act "boat-safaris" "Boat Safaris: Kazinga, Chobe & the Rufiji" "BW" "Eye-level elephants and wallowing hippos from the water." "Slow cruises past elephant herds drinking at the bank, hippo pods, crocodiles and fish eagles - photography at water level with zero dust." "Kazinga Channel (Uganda), Chobe riverfront (Botswana), Rufiji River (Nyerere), Zambezi and Lake Kariba." "Dry season concentrates herds at water; afternoon light photographs best." "Included in most water-adjacent itineraries; private boats 100 to 300 dollars." "Everyone including limited-mobility travelers - boats are the most accessible safari." @(@("/botswana-safari/5-day-botswana-safari/","5-Day Botswana Explorer","5 days","From $3,900","Chobe boat safari included."),@("/uganda-safari/7-day-uganda-safari/","7-Day Uganda","7 days","From $4,100","Kazinga Channel cruise.")) '<a href="/national-parks/chobe/">Chobe</a> | <a href="/national-parks/nyerere/">Nyerere</a>'
New-Act "photographic-safaris" "Photographic Safaris: Hides, Light & Low Mileage" "MIG" "Beanbags, open-vehicle positioning for light, water-level hides, unhurried single-sighting days." "Photography safaris trade mileage for light: one sighting held through golden hour beats five rushed stops. Private vehicles position for sun angle; hides put lenses at eye level." "Serengeti and Mara (herds and cats), Mashatu and Kwara hides (eye-level water), Sabi Sand (leopards)." "Calving season for action; crossings for drama; green season for skies." "Private vehicle essential; photographer-guides and hide fees add 200 to 500 dollars per day over standard." "Serious amateurs to pros. Ask for vehicle charging setups and second-row seat removal." @(@("/tanzania-photographic-safari/8-day-photographic-serengeti/","8-Day Photographic Serengeti","8 days","From $5,400","Light-chasing Migration."),@("/botswana-safari/8-day-botswana-safari/","8-Day Botswana","8 days","From $7,400","Hides and water light.")) '<a href="/africa-photographic-safaris/">Photo hub</a> | <a href="/travel-guide/photography/">Photography guide</a>'
New-Act "cultural-tours" "Cultural Tours: Maasai, Hadzabe, Batwa & Himba" "NA" "Community-led visits arranged respectfully: real villages, real guides, never staged photo stops." "Boma visits with Maasai guides, Hadzabe bushmen walks, Batwa forest heritage, Himba villages - small groups, local payment, genuine exchange." "Northern Tanzania, Damaraland and Kaokoveld, Bwindi surrounds, Omo Valley with community-origin guides." "Year-round; market days add color - ask for weekly schedules." "20 to 60 dollars per person community fees, paid locally; Omo expeditions bundle guiding." "Everyone. Families with kids consistently rate these days highest." @(@("/namibia-safari/7-day-namibia-safari/","7-Day Namibia","7 days","From $2,900","Himba and Damaraland culture."),@("/ethiopia-safari/8-day-ethiopia-historic/","8-Day Ethiopia","8 days","From $3,600","Living history plus trekking.")) '<a href="/tanzania-safari/">Tanzania</a> | <a href="/namibia-safari/">Namibia</a>'
New-Act "bird-watching" "Bird Watching on Safari: 500-Species Zones" "TZ" "Rollers, bee-eaters, raptors and endemics - even non-birders convert by day three." "Tarangire's 500-plus species, Rift Valley lake flocks, green-season migrants and raptor concentrations - with specialist guides on request." "Tarangire, Rift lakes, Okavango, Kruger; green season November to May for migrants." "Green season aligns with lower rates - birding value peaks when crowds trough." "Included in game drives; specialist birding guides 100 to 200 dollars per day." "All levels; bring binoculars per person - sharing ruins it." @(@("/tanzania-safari/6-day-tanzania-safari/","6-Day Tanzania","6 days","From $2,500","Tarangire birding plus icons."),@("/kenya-safari-from-nairobi/5-day-kenya-from-nairobi/","5-Day Mara and Lakes","5 days","From $2,000","Lake flocks plus Mara.")) '<a href="/national-parks/tarangire/">Tarangire</a> | <a href="/travel-guide/best-time-for-african-safari/">Best time</a>'
New-Act "kilimanjaro-trekking" "Kilimanjaro Trekking Routes Compared" "KILI" "Lemosho, Machame, Marangu and Rongai compared honestly - success rates, scenery, crowds, cost." "Africa's highest summit (5,895m) over 5 to 8 days: Lemosho for best acclimatisation, Machame for the classic line, Marangu for huts and budget, Rongai for quiet northern approach." "Kilimanjaro National Park, Tanzania. Combine with northern-circuit safari after - legs recover on game drives." "January to March and June to October dry windows." "Quality climbs 2,800 to 5,500 dollars; below 2,500 means corners cut on crew or days." "Fit hill-walkers; altitude affects everyone - route length beats fitness for summit odds." @(@("/kilimanjaro/lemosho-route/","Lemosho Route (8 Days)","8 days","From $3,400","Highest success rate."),@("/kilimanjaro/machame-route/","Machame Route (7 Days)","7 days","From $2,950","The classic Whiskey route."),@("/kilimanjaro/marangu-route/","Marangu Route (6 Days)","6 days","From $2,600","Hut route with extra day.")) '<a href="/kilimanjaro/">Kilimanjaro hub</a> | <a href="/kilimanjaro/cost/">Cost breakdown</a>'
